sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:Thirumalai_Thenkumari dbr:Devil's_Squadron }

  # director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?directorDBP . }
  OPTIONAL { ?film dbo:director ?directorDBO . }
  BIND (COALESCE(?directorDBP, ?directorDBO) AS ?director)

  # director's birth date (prefer dbp:birthDate, fallback to dbo:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDBP . }
  OPTIONAL { ?director dbo:birthDate ?birthDBO . }
  BIND (COALESCE(?birthDBP, ?birthDBO) AS ?birthDate)
}
LIMIT 100

